-- Add review_summary column to compliance_issue_analyses
-- Generated by the review summary pipeline post-processing step.
-- Contains a 1-2 sentence plain-language summary for quick review triage.
ALTER TABLE compliance_issue_analyses ADD COLUMN review_summary TEXT;

-- Partial index for --summaries-only backfill queries (WHERE review_summary IS NULL)
CREATE INDEX idx_cia_review_summary_null
  ON compliance_issue_analyses(jurisdiction, issue_type)
  WHERE review_summary IS NULL;
